starter:
function toFahrenheit(celsius) {
  // your code here
}

console.log(toFahrenheit(100));

solution:
function toFahrenheit(celsius) {
  // return sends the result back to whoever called the function.
  return celsius * 9 / 5 + 32;
}

console.log(toFahrenheit(100));

starter:
function makeBadge(name, role) {
  // your code here
}

console.log(makeBadge("Ana"));

solution:
// role = "student" is a default parameter:
// it's used when the call doesn't pass a second argument.
function makeBadge(name, role = "student") {
  return name + " (" + role + ")";
}

console.log(makeBadge("Ana"));

alternatives:
function makeBadge(name, role = "student") {
  return `${name} (${role})`;
}

console.log(makeBadge("Ana"));
function makeBadge(name, role) {
  if (role === undefined) {
    role = "student";
  }
  return name + " (" + role + ")";
}

console.log(makeBadge("Ana"));

