}

solution:
let visits = 0;

function registerVisit() {
  // No let here: we want to change the global visits,
  // not create a new local variable that shadows it.
  visits++;
  return visits;
}

alternatives:
let visits = 0;

function registerVisit() {
  visits = visits + 1;
  return visits;
}

