starter:
function applyToAll(list, fn) {
  // your code here
}

console.log(applyToAll([1, 2, 3], (n) => n * 2));

solution:
function applyToAll(list, fn) {
  const result = [];
  for (const item of list) {
    // fn is the callback: we call it with each element
    // and keep what it returns.
    result.push(fn(item));
  }
  return result;
}

console.log(applyToAll([1, 2, 3], (n) => n * 2));

alternatives:
function applyToAll(list, fn) {
  return list.map(fn);
}

console.log(applyToAll([1, 2, 3], (n) => n * 2));
function applyToAll(list, fn) {
  const result = [];
  for (let i = 0; i < list.length; i++) {
    result.push(fn(list[i]));
  }
  return result;
}

console.log(applyToAll([1, 2, 3], (n) => n * 2));

starter:
function repeatText(text, times) {
  // your code here
}

console.log(repeatText("ab", 3));

solution:
function repeatText(text, times) {
  // Base case: nothing left to repeat.
  if (times === 0) {
    return "";
  }
  // Recursive call with one repetition less.
  return text + repeatText(text, times - 1);
}

console.log(repeatText("ab", 3));

alternatives:
function repeatText(text, times) {
  if (times <= 0) return "";
  return repeatText(text, times - 1) + text;
}

console.log(repeatText("ab", 3));

solution:
console.log("Start");
// setTimeout schedules the callback and the program carries on,
// so "End" is printed first and "Done!" 500 ms later.
setTimeout(() => {
  console.log("Done!");
}, 500);

console.log("End");

alternatives:
console.log("Start");
function finish() {
  console.log("Done!");
}
setTimeout(finish, 500);

console.log("End");

starter:
console.log("Countdown:");
// your code here

console.log("Get ready...");

solution:
console.log("Countdown:");
let count = 3;
// setInterval returns an id that clearInterval needs to stop it.
const timer = setInterval(() => {
  if (count > 0) {
    console.log(count);
    count--;
  } else {
    console.log("Go!");
    clearInterval(timer);
  }
}, 200);

console.log("Get ready...");

alternatives:
console.log("Countdown:");
let count = 3;
const timer = setInterval(() => {
  console.log(count === 0 ? "Go!" : count);
  if (count === 0) {
    clearInterval(timer);
  }
  count--;
}, 200);

console.log("Get ready...");
